import{_ as a,o as e,c as o,a2 as l}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 20 章 记忆系统进阶：长期协作上下文","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 20 章 记忆系统进阶：长期协作上下文.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 20 章 记忆系统进阶：长期协作上下文.md"}'),s={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 20 章 记忆系统进阶：长期协作上下文.md"};function i(n,t,r,d,p,u){return e(),o("div",null,[...t[0]||(t[0]=[l(`<h1 id="第-20-章-记忆系统进阶-长期协作上下文" tabindex="-1">第 20 章 记忆系统进阶：长期协作上下文 <a class="header-anchor" href="#第-20-章-记忆系统进阶-长期协作上下文" aria-label="Permalink to &quot;第 20 章 记忆系统进阶：长期协作上下文&quot;">​</a></h1><h2 id="_20-1-从-记住-到-协作上下文" tabindex="-1">20.1 从&quot;记住&quot;到&quot;协作上下文&quot; <a class="header-anchor" href="#_20-1-从-记住-到-协作上下文" aria-label="Permalink to &quot;20.1 从&quot;记住&quot;到&quot;协作上下文&quot;&quot;">​</a></h2><p>第 6 章讲了记忆的基础用法。这一章进阶：把记忆从&quot;几条偏好&quot;升级成<strong>你和 AI 之间的长期协作上下文</strong>——让任何一次新会话，都像老搭档接着聊。</p><h2 id="_20-2-记忆的四种类型回顾" tabindex="-1">20.2 记忆的四种类型回顾 <a class="header-anchor" href="#_20-2-记忆的四种类型回顾" aria-label="Permalink to &quot;20.2 记忆的四种类型回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>用途</th><th>例子</th></tr></thead><tbody><tr><td>user</td><td>关于你</td><td>身份、角色、工作背景</td></tr><tr><td>feedback</td><td>你的反馈</td><td>风格偏好、踩过的坑</td></tr><tr><td>project</td><td>项目上下文</td><td>项目目标、决策、现状</td></tr><tr><td>reference</td><td>参考资料</td><td>模板、规范、参考文档</td></tr></tbody></table><p><strong>进阶心法：记忆不是&quot;存档&quot;，而是&quot;上下文&quot;。</strong> 好的记忆，让我在新任务里少问 10 个问题。</p><h2 id="_20-3-长期协作上下文怎么建立" tabindex="-1">20.3 长期协作上下文怎么建立 <a class="header-anchor" href="#_20-3-长期协作上下文怎么建立" aria-label="Permalink to &quot;20.3 长期协作上下文怎么建立&quot;">​</a></h2><p><strong>第一步：初始化（一次性投入）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;记住：我是产品经理，主要做 B 端 SaaS；文档偏好结论先行、</span></span>
<span class="line"><span>中文简洁；所有交付物用 Markdown；我所在项目是 XX。&quot;</span></span></code></pre></div><p><strong>第二步：运行期沉淀（持续投入）</strong></p><p>每次任务结束，沉淀一条：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务做完后 → 记录：项目当前状态、下一步计划、本轮的坑</span></span></code></pre></div><p><strong>第三步：定期整理（维护）</strong></p><ul><li>过期记忆删除或更新；</li><li>重复记忆合并；</li><li>索引（MEMORY.md）保持整洁，一条一行。</li></ul><h2 id="_20-4-记忆的最佳实践" tabindex="-1">20.4 记忆的最佳实践 <a class="header-anchor" href="#_20-4-记忆的最佳实践" aria-label="Permalink to &quot;20.4 记忆的最佳实践&quot;">​</a></h2><p><strong>值得长期记忆的：</strong></p><ul><li>稳定的工作方式（&quot;我每周五要周报&quot;）；</li><li>关键决策与原因（&quot;我们选 A 方案因为成本，别再说 B&quot;）；</li><li>名词解释（团队内部术语，每次都要解释太浪费）。</li></ul><p><strong>不值得记忆的：</strong></p><ul><li>一次性数据（放项目文件）；</li><li>会变的内容（放文件或数据库）；</li><li>敏感信息（明文记忆文件，不存密钥密码）。</li></ul><h2 id="_20-5-记忆的治理与隐私" tabindex="-1">20.5 记忆的治理与隐私 <a class="header-anchor" href="#_20-5-记忆的治理与隐私" aria-label="Permalink to &quot;20.5 记忆的治理与隐私&quot;">​</a></h2><ul><li>记忆文件是<strong>明文</strong>，放在项目对应目录，你可以随时读；</li><li>你可以随时删除：&quot;忘掉 XXX&quot;；</li><li>敏感项目：注意记忆文件不要提交到公开仓库；</li><li>团队协作：共享项目的记忆是团队资产，写入前想清楚。</li></ul><h2 id="_20-6-记忆让-老搭档-成为可能" tabindex="-1">20.6 记忆让&quot;老搭档&quot;成为可能 <a class="header-anchor" href="#_20-6-记忆让-老搭档-成为可能" aria-label="Permalink to &quot;20.6 记忆让&quot;老搭档&quot;成为可能&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>没有记忆的 AI：每次都是新员工，从头自我介绍</span></span>
<span class="line"><span>有记忆的 AI：知道你是谁、在做什么、偏好什么、上次聊到哪</span></span></code></pre></div><p>这套上下文，是第 17 章 Skill、第 18 章系统、第 19 章自动化的<strong>底座</strong>——它们都要靠记忆来&quot;认得你&quot;。</p><h2 id="_20-7-练习" tabindex="-1">20.7 练习 <a class="header-anchor" href="#_20-7-练习" aria-label="Permalink to &quot;20.7 练习&quot;">​</a></h2><ol><li>花 10 分钟做一次&quot;记忆初始化&quot;：身份、偏好、项目、常用格式；</li><li>本周每次任务完成后，沉淀一条 project/feedback 记忆；</li><li>周末检查 MEMORY.md 索引，合并重复、删除过期。</li></ol><blockquote><p>小结：记忆系统是<strong>时间的朋友</strong>。用得越久，我越懂你；越懂你，每次任务就越省沟通、越少返工。</p></blockquote>`,27)])])}const _=a(s,[["render",i]]);export{c as __pageData,_ as default};
